<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserConsentedScopes\Domain\Gateway;

use Civi\Lughauth\Features\Access\UserConsentedScopes\Domain\UserConsentedScopes;

class UserConsentedScopesCursor
{
    public function __construct(
        private int $limit,
        private ?string $sinceUid = null,
    ) {
    }
    public function next(UserConsentedScopes $userConsentedScopes, ?int $size): UserConsentedScopesCursor
    {
        $next = clone $this;
        $next->sinceUid = $userConsentedScopes->uid();
        $next->limit = $size ?? $this->limit;
        return $next;
    }
    public function limit(): int
    {
        return $this->limit;
    }
    public function sinceUid(): ?string
    {
        return $this->sinceUid;
    }
}
